export interface NavItem { readonly id: string; readonly label: string; }
export interface MenuSnapshot { readonly mobile: boolean; readonly expanded: boolean; readonly items: readonly NavItem[]; }

export class ResponsiveMenu {
  private width: number;
  private expanded: boolean;
  private readonly items: NavItem[];

  constructor(items: readonly NavItem[], width: number) {
    if (items.length === 0) throw new TypeError("items required");
    this.assertWidth(width);
    const seen = new Set<string>();
    this.items = items.map(item => {
      const id = item.id.trim();
      const label = item.label.trim();
      if (!id || !label || seen.has(id)) throw new TypeError("invalid item");
      seen.add(id);
      return { id, label };
    });
    this.width = width;
    this.expanded = width >= 767;
  }

  resize(width: number): void {
    this.assertWidth(width);
    this.width = width;
    if (width > 767) this.expanded = true;
  }

  toggle(): boolean {
    if (this.width > 767) return false;
    this.expanded = !this.expanded;
    return true;
  }

  snapshot(): MenuSnapshot {
    return {
      mobile: this.width <= 767,
      expanded: this.expanded,
      items: this.expanded ? this.items.map(item => ({ ...item })) : []
    };
  }

  private assertWidth(width: number): void {
    if (!Number.isInteger(width) || width < 0) throw new TypeError("invalid width");
  }
}

