import { ResponsiveMenu } from './solution';

function eq(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message + ': ' + JSON.stringify(actual));
}
function throwsType(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) { if (error instanceof TypeError) return; throw error; }
  throw new Error(message);
}

const source: any[] = [{ id: ' home ', label: ' Home ' }, { id: 'about', label: ' About us ' }];
const mobile = new ResponsiveMenu(source, 767);
source[0].id = 'changed';
source[0].label = 'Changed';
source.push({ id: 'extra', label: 'Extra' });
let snap: any = mobile.snapshot();
eq(snap.expanded, false, 'mobile initially collapsed');
eq(snap.items, [], 'collapsed snapshot hides items');

const collapsedCopy: any = mobile.snapshot();
collapsedCopy.items.push({ id: 'fake', label: 'Fake' });
eq((mobile.snapshot() as any).items, [], 'collapsed item array detached');
eq(mobile.toggle(), true, 'mobile toggle changes state');
snap = mobile.snapshot() as any;
eq(snap.expanded, true, 'mobile expands');
eq(snap.items, [{ id: 'home', label: 'Home' }, { id: 'about', label: 'About us' }], 'items trimmed and ordered');
snap.items[0].id = 'mutated';
snap.items[0].label = 'mutated';
snap.items.pop();
eq((mobile.snapshot() as any).items, [{ id: 'home', label: 'Home' }, { id: 'about', label: 'About us' }], 'snapshot deeply detached');

mobile.resize(400);
eq((mobile.snapshot() as any).expanded, true, 'mobile resize preserves expanded state');
eq(mobile.toggle(), true, 'second mobile toggle changes state');
eq((mobile.snapshot() as any).expanded, false, 'mobile collapses');
mobile.resize(767);
eq((mobile.snapshot() as any).expanded, false, 'mobile boundary preserves state');
mobile.resize(768);
eq((mobile.snapshot() as any).expanded, true, 'desktop forced expanded');
eq(mobile.toggle(), false, 'desktop toggle does nothing');
eq((mobile.snapshot() as any).expanded, true, 'desktop remains expanded');
mobile.resize(1200);
eq((mobile.snapshot() as any).expanded, true, 'desktop resize stays expanded');
mobile.resize(600);
eq((mobile.snapshot() as any).expanded, true, 'desktop expanded state carries into mobile');

const beforeBadResize = JSON.stringify(mobile.snapshot());
for (const width of [-1, 1.5, NaN, Infinity]) {
  throwsType(() => mobile.resize(width), 'invalid width rejected');
  eq(JSON.stringify(mobile.snapshot()), beforeBadResize, 'invalid resize is atomic');
}

throwsType(() => new ResponsiveMenu([], 100), 'empty items rejected');
throwsType(() => new ResponsiveMenu([{ id: ' ', label: 'Label' }] as any, 100), 'blank id rejected');
throwsType(() => new ResponsiveMenu([{ id: 'id', label: ' ' }] as any, 100), 'blank label rejected');
throwsType(() => new ResponsiveMenu([{ id: ' same ', label: 'One' }, { id: 'same', label: 'Two' }] as any, 100), 'trimmed duplicate ids rejected');
throwsType(() => new ResponsiveMenu([{ id: 'id', label: 'Label' }] as any, -1), 'invalid construction width rejected');

